export const CATEGORIES={all:'Todos',anime:'Animes',film:'Filmes',series:'Séries'};

export const ROLES={goku:'ranged',naruto:'explosive',luffy:'melee',gojo:'explosive',ichigo:'melee',tanjiro:'melee',vader:'melee',yoda:'support',spiderman:'ranged',elsa:'explosive',eleven:'explosive',wednesday:'control',vegeta:'ranged',sasuke:'melee',saitama:'melee',bakugo:'explosive',ironman:'ranged',thor:'explosive',harry:'ranged',geralt:'melee'};
for(const [id,d]of Object.entries(TYPES))d.role=ROLES[id];
// GOD modifiers alter the actual simulation, not just visual effects.
export function modifiers(type,god=false){const def=TYPES[type],role=def.role,ranged=def.range>3||role==='ranged',melee=def.range<=3||role==='melee';return {projectiles:god&&ranged?100:1,knockback:god&&melee?100:1,defense:god&&melee?10:1,blast:god&&role==='explosive'?100:1,radius:god&&['explosive','support','control'].includes(role)?10:1,healing:god&&role==='support'?100:1,control:god&&role==='control'?100:1};}
export function unitCost(type,god=false){return TYPES[type].cost;}
export function godDescription(type){const m=modifiers(type,true),parts=[];if(m.projectiles>1)parts.push('100× projéteis');if(m.knockback>1)parts.push('100× empurrão','10× defesa');if(m.blast>1)parts.push('100× dano explosivo','10× raio');if(m.healing>1)parts.push('100× cura','10× alcance de suporte');if(m.control>1)parts.push('100× duração do controle','10× raio de controle');return parts.join(' · ');}
